TOPICS = []
def add(field, slug, title, summary, formula, prerequisites, definitions, theorems, applications, pitfalls, exercises, related):
    TOPICS.append(dict(field=field, slug=slug, title=title, summary=summary, formula=formula, prerequisites=prerequisites, definitions=definitions, theorems=theorems, applications=applications, pitfalls=pitfalls, exercises=exercises, related=related))

add('foundations','sets-maps','Sets & maps','Specify the objects and the maps between them before manipulating either.',
 'f⁻¹(B) = {x ∈ X : f(x) ∈ B}', [],
 [('Function','A function f: X → Y assigns exactly one element of Y to each element of X. X is the domain, Y the codomain, and f(X) the image.'),('Injective, surjective, bijective','Injective means f(x)=f(x′) implies x=x′. Surjective means f(X)=Y. Bijective means both.'),('Equivalence relation','A relation that is reflexive, symmetric, and transitive. Its equivalence classes partition the set.')],
 [('Inverse criterion','A function has a two-sided inverse exactly when it is bijective.'),('Preimages preserve set operations','For any function, preimages preserve unions, intersections, and complements relative to the domain and codomain.')],
 [('Quotient constructions','Identify objects related by an equivalence relation: congruence classes, quotient groups, and spaces of solutions.'),('Data transformations','Injectivity records whether a transformation loses information; surjectivity records whether every target can be reached.')],
 ['A codomain is part of the definition. x ↦ x² is not surjective onto ℝ, but is surjective onto [0,∞).','The notation f⁻¹(B) for a preimage does not require an inverse function.'],
 [('Compute','For f: ℝ → ℝ, f(x)=x², find f⁻¹([1,4]).','Solve 1 ≤ x² ≤ 4.','The preimage is [−2,−1] ∪ [1,2].'),('Prove','Show f⁻¹(A ∩ B)=f⁻¹(A) ∩ f⁻¹(B).','Follow one arbitrary element through both membership statements.','x belongs to the left side iff f(x) belongs to both A and B, iff x belongs to both preimages. Thus the sets have the same elements.')], ['foundations/proof','groups/quotients'])

add('foundations','proof','Proof techniques','Choose the logical shape of an argument before choosing its algebra.',
 'P ⇒ Q  ⇔  ¬Q ⇒ ¬P', ['foundations/sets-maps'],
 [('Direct proof','Assume the hypotheses and derive the conclusion.'),('Contradiction','Assume the negation of the desired claim and derive an impossibility.'),('Induction','Prove a base case and a step from a statement at n to the statement at n+1.')],
 [('Induction principle','If P(0) holds and P(n) implies P(n+1) for every integer n≥0, then P(n) holds for every integer n≥0.'),('Well-ordering of ℕ','Every nonempty subset of the nonnegative integers has a least element; this supports minimal-counterexample arguments.')],
 [('Algorithms','Loop invariants and induction establish that repeated operations preserve correctness.'),('Structure theorems','Induction on dimension or group order reduces large objects to smaller ones.')],
 ['The converse Q ⇒ P does not follow from P ⇒ Q.','To refute “for every,” one counterexample suffices; checking examples cannot prove an infinite universal claim.'],
 [('Prove','Prove 1+⋯+n=n(n+1)/2 for n≥1.','Add n+1 to the induction hypothesis.','The base case is 1=1. If the formula holds at n, the next sum is n(n+1)/2+(n+1)=(n+1)(n+2)/2.'),('Find a counterexample','Is every continuous real function differentiable?','Look for a corner.','No. f(x)=|x| is continuous everywhere, but its left and right derivatives at 0 are −1 and 1.')], ['calculus/limits','groups/basics'])

add('algebra','polynomials','Polynomials & roots','Factorization translates an equation into structural information about its roots.',
 'p(x) = (x − a)q(x) + p(a)', ['foundations/sets-maps'],
 [('Polynomial over a field','A finite sum a₀+a₁x+⋯+aₙxⁿ with coefficients in a field F. A nonzero polynomial has degree equal to its highest nonzero exponent.'),('Root and multiplicity','a is a root if p(a)=0; it has multiplicity m if (x−a)ᵐ divides p but (x−a)ᵐ⁺¹ does not.'),('Irreducible polynomial','A nonconstant polynomial that cannot be factored into two positive-degree polynomials over the specified field.')],
 [('Division algorithm','For p,d ∈ F[x] with d≠0, there are unique q,r with p=qd+r and either r=0 or deg r<deg d.'),('Root bound','A nonzero degree-n polynomial over a field has at most n distinct roots.'),('Fundamental theorem of algebra','Every nonconstant complex polynomial has a complex root, hence factors into linear factors over ℂ.')],
 [('Eigenvalues','The roots of det(λI−A) are precisely the eigenvalues of a square matrix.'),('Interpolation','Distinct sample locations determine a unique polynomial of degree at most n−1 through n prescribed values.')],
 ['Irreducibility depends on the field: x²+1 is irreducible over ℝ but not ℂ.','A repeated root counts multiple times in factorization, but only once as a distinct root.'],
 [('Compute','Factor x³−3x²+3x−1 and give its roots with multiplicities.','Compare with a binomial cube.','It is (x−1)³. The only root is 1, of multiplicity 3.'),('Prove','Why must two degree-at-most-2 polynomials agreeing at three distinct points be identical?','Subtract them and use the root bound.','Their difference has degree at most 2 and at least 3 distinct roots. It must be the zero polynomial.')], ['algebra/rings-fields','linear-algebra/eigenvalues'])

add('algebra','rings-fields','Rings, ideals & fields','Track which arithmetic operations are available and which survive a quotient.',
 'F[x] / (p) is a field ⇔ p is irreducible  (p nonconstant)', ['algebra/polynomials','groups/quotients'],
 [('Commutative ring with identity','An abelian additive group with associative, commutative multiplication, a multiplicative identity, and distributivity. All rings on this sheet use this convention.'),('Ideal','An additive subgroup I⊆R such that ri∈I for every r∈R and i∈I. This makes multiplication of cosets well-defined.'),('Field','A nonzero commutative ring in which every nonzero element has a multiplicative inverse.')],
 [('Quotient field criterion','For a commutative ring with identity, R/I is a field exactly when I is a maximal proper ideal.'),('Prime integer modulus','ℤ/nℤ is a field exactly when n is prime, for integers n≥2.')],
 [('Finite arithmetic','Finite fields support algebraic error-correcting codes and exact computations.'),('Adjoining a root','The quotient ℝ[x]/(x²+1) realizes ℂ by making the class of x square to −1.')],
 ['A nonzero element of a ring need not be invertible, and cancellation can fail in the presence of zero divisors.','An additive subgroup need not be an ideal.'],
 [('Compute','Find the inverse of 3 in ℤ/7ℤ.','Find k with 3k≡1 mod 7.','The inverse is 5 because 3·5=15≡1 mod 7.'),('Explain','Why is ℤ/6ℤ not a field?','Multiply the classes of 2 and 3.','They are both nonzero but their product is zero. If 2 had an inverse, multiplying 2·3=0 by it would imply 3=0, a contradiction.')], ['groups/quotients','algebra/polynomials'])

add('linear-algebra','spaces-maps','Vector spaces & linear maps','Separate coordinate-free objects from the matrices used to describe them.',
 'dim V = dim ker T + dim im T', ['foundations/sets-maps'],
 [('Vector space','A set with vector addition and scalar multiplication over a field F satisfying the usual distributive, associative, identity, and inverse axioms.'),('Basis','A linearly independent spanning set. In finite dimension, each vector has a unique linear combination in that basis.'),('Kernel and image','For a linear map T: V→W, ker T={v:T(v)=0} and im T={T(v):v∈V}; both are subspaces.')],
 [('Rank–nullity','For T: V→W with V finite-dimensional, dim V=dim ker T+dim im T.'),('Basis extension','Every linearly independent set in a finite-dimensional vector space extends to a basis.')],
 [('Constraints','Null spaces describe motions or parameter changes that preserve linear constraints.'),('Representations','A group can act by invertible linear maps on a vector space, turning symmetry into linear algebra.')],
 ['A matrix changes when bases change; the underlying linear map does not.','A set containing the zero vector cannot be linearly independent.'],
 [('Compute','For T(x,y,z)=(x+y,y+z), find a basis of ker T and the rank.','Solve x+y=0 and y+z=0.','The kernel is span{(−1,1,−1)}, so nullity=1 and rank=3−1=2.'),('Prove','Show that an injective linear map between two finite-dimensional spaces of the same dimension is surjective.','Injectivity means the kernel is zero.','Rank–nullity gives rank T=dim V=dim W, so the image subspace is all of W.')], ['linear-algebra/eigenvalues','representations/basics'])

add('linear-algebra','eigenvalues','Eigenvalues & diagonalization','Find directions on which a linear transformation acts only by scaling.',
 'Av = λv,  v ≠ 0;     A = PDP⁻¹', ['linear-algebra/spaces-maps','algebra/polynomials'],
 [('Eigenvalue and eigenspace','λ is an eigenvalue when ker(A−λI) is nonzero. That kernel is the eigenspace, including its zero vector.'),('Diagonalizable','A square matrix over F is diagonalizable over F if it has a basis of eigenvectors in Fⁿ.'),('Algebraic vs geometric multiplicity','Algebraic multiplicity is multiplicity in the characteristic polynomial; geometric multiplicity is the eigenspace dimension.')],
 [('Distinct eigenvalues','Eigenvectors for distinct eigenvalues are linearly independent. In particular, n distinct eigenvalues imply diagonalizability of an n×n matrix.'),('Spectral theorem','Every real symmetric matrix has an orthonormal eigenbasis and real eigenvalues. Every complex Hermitian matrix has a unitary diagonalization with real eigenvalues.')],
 [('Dynamics','Diagonalization simplifies powers Aᵏ and solutions of x′=Ax.'),('Principal components','Eigenvectors of a covariance matrix identify orthogonal directions of variance.')],
 ['Repeated eigenvalues do not automatically prevent diagonalization.','A real matrix may need complex scalars to have eigenvectors: a planar rotation through an angle not divisible by π is an example.'],
 [('Compute','Diagonalize A=[[2,1],[1,2]] with an orthonormal basis.','Try vectors (1,1) and (1,−1).','The unit eigenvectors are (1,1)/√2 with λ=3 and (1,−1)/√2 with λ=1. Put these as columns of Q: A=Q diag(3,1) Qᵀ.'),('Explain','Is [[1,1],[0,1]] diagonalizable?','Compute ker(A−I).','No. Its only eigenvalue is 1 and its eigenspace consists of (x,0), so it has dimension 1 rather than 2.'),('Check an assumption','For A=[[1,1],[0,1]], compute Aⁿ for n≥1. Why does the eigenvalue alone miss part of the behavior?','Write A=I+N and check N².','N=[[0,1],[0,0]] has N²=0. The binomial expansion gives Aⁿ=I+nN=[[1,n],[0,1]]. Although the sole eigenvalue is 1, the off-diagonal term grows linearly because A has a nontrivial Jordan block.')], ['linear-algebra/orthogonality','statistics/regression','representations/characters'])

add('linear-algebra','orthogonality','Orthogonality, least squares & SVD','Approximate a vector by its closest point in a subspace.',
 'AᵀAx̂ = Aᵀb;     A = UΣVᵀ', ['linear-algebra/spaces-maps'],
 [('Inner product','Over ℝ, a symmetric positive-definite bilinear form. It defines a norm by ‖v‖=√⟨v,v⟩ and orthogonality by ⟨u,v⟩=0.'),('Orthogonal projection','The unique closest vector to b in a finite-dimensional inner-product subspace S. Its residual is orthogonal to S.'),('Singular values','The nonnegative square roots of the eigenvalues of AᵀA for a real matrix A.')],
 [('Projection theorem','A vector p∈S minimizes ‖b−p‖ exactly when b−p is orthogonal to S.'),('Normal equations','Every least-squares minimizer solves AᵀAx=Aᵀb. The coefficient vector is unique if A has full column rank.'),('Singular value decomposition','Every real m×n matrix has A=UΣVᵀ with orthogonal U,V and rectangular diagonal Σ with nonnegative entries. Complex matrices use conjugate transpose.')],
 [('Regression','Least squares fits a response vector to the column space of a design matrix.'),('Compression','Truncating the SVD to the k largest singular values gives a best rank-at-most-k approximation in Frobenius norm.')],
 ['Normal equations are a characterization, not always a numerically good algorithm; QR or SVD avoids squaring the condition number.','Orthogonality depends on the chosen inner product.'],
 [('Compute','Project b=(2,0) onto span{(1,1)}.','Use ⟨b,u⟩u/⟨u,u⟩.','The projection is (1,1); the residual (1,−1) is orthogonal to (1,1).'),('Compute','Find the singular values of diag(3,−2,0).','Use AᵀA.','AᵀA=diag(9,4,0), so the singular values are 3, 2, and 0.')], ['statistics/regression','linear-algebra/eigenvalues'])

add('calculus','limits','Limits & continuity','Make approximation statements precise by controlling errors.',
 '∀ε>0 ∃δ>0: 0<|x−a|<δ ⇒ |f(x)−L|<ε', ['foundations/proof'],
 [('Limit','The displayed condition defines limₓ→ₐ f(x)=L, with x restricted to the domain and a an accumulation point.'),('Continuity','f is continuous at a if f(a) is defined and limₓ→ₐ f(x)=f(a).'),('Uniform continuity','For every ε>0 one δ>0 works for every pair of points in the domain whose distance is below δ.')],
 [('Intermediate value theorem','A continuous real function on [a,b] takes every value between f(a) and f(b).'),('Extreme value theorem','A continuous real function on a compact interval attains both a maximum and a minimum.'),('Heine–Cantor','A continuous function on a compact metric space is uniformly continuous.')],
 [('Root finding','A sign change of a continuous function brackets a root and justifies bisection.'),('Stable approximation','Uniform continuity controls errors across an entire domain rather than at one input.')],
 ['The function need not be defined at a for its limit at a to exist.','A continuous function on an open or unbounded interval need not attain its extrema.'],
 [('Prove','Show limₓ→₂(3x+1)=7 directly.','Express the output error in terms of |x−2|.','Given ε>0, choose δ=ε/3. If 0<|x−2|<δ, then |3x+1−7|=3|x−2|<ε.'),('Find a counterexample','Give a bounded continuous function on (0,1) with no maximum.','Consider the identity function.','f(x)=x is bounded and continuous, but for every x∈(0,1), (x+1)/2 is a larger input with a larger value.')], ['calculus/derivatives','calculus/integrals'])

add('calculus','derivatives','Derivatives & Taylor expansion','The derivative is a local linear model; Taylor expansion adds controlled higher-order terms.',
 'f(a+h) = f(a) + f′(a)h + o(h)', ['calculus/limits'],
 [('Derivative','f′(a)=limₕ→₀ [f(a+h)−f(a)]/h when the limit exists.'),('Critical point','An interior point at which the derivative is zero or does not exist; these are candidates for local extrema.'),('Taylor polynomial','The degree-n polynomial at a with coefficients f⁽ᵏ⁾(a)/k!, for 0≤k≤n.')],
 [('Mean value theorem','If f is continuous on [a,b] and differentiable on (a,b), then some c∈(a,b) satisfies f′(c)=[f(b)−f(a)]/(b−a).'),('Taylor remainder','If f is Cⁿ⁺¹ on an interval containing a and x, then f(x)=Σₖ₌₀ⁿ f⁽ᵏ⁾(a)(x−a)ᵏ/k! + f⁽ⁿ⁺¹⁾(ξ)(x−a)ⁿ⁺¹/(n+1)! for some ξ between a and x.'),('Chain rule','If g is differentiable at x and f at g(x), then (f∘g)′(x)=f′(g(x))g′(x).')],
 [('Optimization','Derivatives identify stationary candidates and monotonicity intervals.'),('Numerical approximation','Taylor bounds quantify approximation error, rather than just providing a polynomial guess.')],
 ['A zero derivative at a point does not imply an extremum: x³ at 0.','An infinitely differentiable function need not equal its Taylor series.'],
 [('Compute','Differentiate exp(x²).','Apply the chain rule.','The derivative is 2x exp(x²).'),('Bound','Bound the error of 1+x+x²/2 as an approximation to exp(x) on |x|≤0.1.','Bound the third derivative on [−0.1,0.1].','The error is at most exp(0.1)|x|³/6 ≤ exp(0.1)/6000, approximately 0.0001842.')], ['calculus/multivariable','calculus/integrals'])

add('calculus','integrals','Integration & accumulation','Integrals combine local contributions; the fundamental theorem links accumulation and change.',
 '∫ₐᵇ f(x) dx = F(b) − F(a),  F′=f', ['calculus/limits','calculus/derivatives'],
 [('Riemann integral','A limit of tagged partition sums as the mesh tends to zero, when all such sums converge to the same number.'),('Antiderivative','A function F with F′=f on an interval.'),('Improper integral','A limit of integrals when an endpoint is infinite or the integrand is unbounded; convergence must be checked.')],
 [('Fundamental theorem of calculus','If f is continuous on [a,b], then A(x)=∫ₐˣ f(t)dt satisfies A′(x)=f(x) in the interior, and any antiderivative evaluates the integral by endpoint subtraction.'),('Integration by parts','For continuously differentiable u,v on [a,b], ∫ₐᵇ uv′=[uv]ₐᵇ−∫ₐᵇ u′v.'),('p-integral test','∫₁∞ x⁻ᵖ dx converges exactly for p>1; ∫₀¹ x⁻ᵖ dx converges exactly for p<1.')],
 [('Probability densities','Integrating a density over a set yields its probability.'),('Physical accumulation','Integrate velocity for displacement, or force along a line for work.')],
 ['A signed integral differs from total geometric area.','Never cancel two divergent improper integrals as if they were finite numbers.'],
 [('Compute','Evaluate ∫₀¹ x eˣ dx.','Take u=x and v′=eˣ.','An antiderivative is (x−1)eˣ. Evaluation gives 0−(−1)=1.'),('Decide','Does ∫₁∞ 1/√x dx converge?','Use p=1/2.','No. Its integral to R is 2√R−2, which tends to infinity.')], ['probability/random-variables','calculus/multivariable'])

add('calculus','multivariable','Gradients, Hessians & change of variables','Local geometry is encoded by first and second derivatives.',
 'Df(x)[h] = ∇f(x)·h;     Hᵢⱼ = ∂²f / ∂xᵢ∂xⱼ', ['calculus/derivatives','linear-algebra/eigenvalues'],
 [('Gradient','For a differentiable scalar function on Euclidean space, the vector representing its derivative under the Euclidean inner product.'),('Jacobian','The matrix of first partial derivatives of a differentiable vector-valued map.'),('Hessian','The matrix of second partial derivatives of a scalar function; symmetric when the second partials are continuous.')],
 [('Second derivative test','At a critical point of a C² function, a positive-definite Hessian gives a strict local minimum, negative-definite a strict local maximum, and indefinite a saddle. Semidefinite cases are inconclusive.'),('Change of variables','For a C¹ diffeomorphism φ between open regions and an integrable function, integration transforms using |det Dφ| as the volume factor.'),('Lagrange multipliers','At a constrained local extremum of differentiable f under g(x)=c, if ∇g≠0, then ∇f=λ∇g for some λ.')],
 [('Optimization','Gradients guide descent and Hessians describe local curvature.'),('Density transformations','The Jacobian determinant converts probability densities between coordinate systems.')],
 ['Existence of partial derivatives alone does not imply differentiability.','The Jacobian volume factor uses an absolute value; orientation is a separate issue.'],
 [('Classify','Classify the origin for f(x,y)=x²−y².','Find the Hessian eigenvalues.','∇f(0,0)=0 and H=diag(2,−2), so the origin is a saddle.'),('Compute','Compute the area of a disk of radius R using polar coordinates.','The Jacobian factor is r.','Integrate ∫₀²π∫₀ᴿ r dr dθ=πR², including the Jacobian factor r.')], ['statistics/regression','probability/random-variables'])

add('probability','conditioning','Events, conditioning & Bayes','Update probabilities by restricting the sample space and renormalizing.',
 'P(A|B) = P(B|A)P(A) / P(B),  P(B)>0', ['foundations/sets-maps'],
 [('Probability space','A triple (Ω,ℱ,P): outcomes, a σ-algebra of events, and a countably additive measure with P(Ω)=1.'),('Conditional probability','For P(B)>0, P(A|B)=P(A∩B)/P(B).'),('Independence','A and B are independent if P(A∩B)=P(A)P(B). A family is mutually independent when the product rule holds for every finite subfamily.')],
 [('Total probability','For a countable partition {Bᵢ} with positive probabilities, P(A)=ΣᵢP(A|Bᵢ)P(Bᵢ).'),('Bayes rule','The displayed identity follows by writing the joint probability in two ways; the denominator can be expanded by total probability.')],
 [('Classification','Combine prior class probabilities with evidence likelihoods.'),('Reliability','Break a system into operating scenarios and combine conditional failure probabilities.')],
 ['P(A|B) and P(B|A) are generally different.','Disjoint positive-probability events cannot be independent.'],
 [('Compute','A factory uses machine A for 60% of parts and B for 40%. Defect rates are 1% and 3%. Given a defective part, what is the probability it came from B?','Compute the total defect rate first.','P(defect)=0.6·0.01+0.4·0.03=0.018. Thus P(B|defect)=0.012/0.018=2/3.'),('Explain','For a fair die, are “even” and “greater than 3” independent?','Compare the joint probability with the product.','The joint event is {4,6}, with probability 1/3. The product is (1/2)(1/2)=1/4, so they are not independent.')], ['probability/random-variables','statistics/estimation'])

add('probability','random-variables','Random variables & moments','A distribution describes a random quantity; moments summarize selected features.',
 'Var(X) = E[X²] − E[X]²', ['probability/conditioning','calculus/integrals'],
 [('Random variable','A measurable function from a probability space to ℝ. Its distribution assigns probabilities to values or sets of values.'),('Expectation','For discrete X, E[X]=Σₓ xP(X=x); for a density f, E[X]=∫xf(x)dx, when absolutely integrable.'),('Variance and covariance','Var(X)=E[(X−E[X])²]; Cov(X,Y)=E[(X−E[X])(Y−E[Y])], assuming finite second moments.')],
 [('Linearity of expectation','E[aX+bY]=aE[X]+bE[Y] for integrable X,Y, without requiring independence.'),('Variance of a sum','Var(X+Y)=Var(X)+Var(Y)+2Cov(X,Y). Independence with finite second moments implies zero covariance.'),('Total expectation','For integrable X and a random variable Y, E[E[X|Y]]=E[X].')],
 [('Risk and variability','Means describe location while variance describes squared spread; neither alone identifies a general distribution.'),('Monte Carlo','Average function values at random samples to estimate expectations and integrals.')],
 ['A density value is not a point probability and can exceed 1.','Zero covariance does not imply independence in general.'],
 [('Compute','Let X be Bernoulli(p). Find E[X] and Var(X).','X²=X.','E[X]=p and E[X²]=p, hence Var(X)=p−p²=p(1−p).'),('Explain','For X uniform on [−1,1] and Y=X², show zero covariance but dependence.','Use symmetry for the odd moments.','E[X]=E[X³]=0, so Cov(X,X²)=0. But Y is determined by X and is nonconstant; for example Y≤1/4 exactly when |X|≤1/2, so independence fails.')], ['probability/limits','statistics/estimation'])

add('probability','limits','LLN, CLT & concentration','Understand what averaging guarantees—and how much data a guarantee needs.',
 '√n (X̄ₙ − μ) / σ  ⇒  N(0,1)', ['probability/random-variables'],
 [('Convergence in probability','Xₙ→X in probability if P(|Xₙ−X|>ε)→0 for every ε>0.'),('Convergence in distribution','The distribution functions converge at every continuity point of the limiting distribution function.'),('Sample mean','X̄ₙ=(X₁+⋯+Xₙ)/n. Its behavior depends on assumptions about the sample, not just this formula.')],
 [('Weak law of large numbers','For iid random variables with finite mean μ, X̄ₙ→μ in probability.'),('Classical central limit theorem','For iid variables with mean μ and finite variance 0<σ²<∞, the standardized sample mean in the display converges in distribution to a standard normal.'),('Chebyshev inequality','For finite variance and t>0, P(|X−E[X]|≥t)≤Var(X)/t².')],
 [('Error bars','CLT approximations explain the common 1/√n scale of sampling error.'),('Simulation budgets','Concentration bounds provide finite-sample error guarantees, although they may be conservative.')],
 ['The CLT is asymptotic; it does not say every sample of size 30 is approximately normal.','The LLN does not promise that each successive sample mean is closer to μ.'],
 [('Bound','For iid samples of variance 4, bound P(|X̄ₙ−μ|≥0.5) using Chebyshev.','Var(X̄ₙ)=4/n.','The bound is (4/n)/0.25=16/n, or min(1,16/n). To make it at most 0.05, take n≥320.'),('Compute','If a mean estimate has standard error 0.2 with n samples, how many samples target 0.1 under the same iid variance?','Standard error scales as n⁻¹ᐟ².','Four times as many samples: σ/√(4n) is half of σ/√n.')], ['statistics/inference','statistics/estimation'])

add('statistics','estimation','Estimation & likelihood','Choose a model, then distinguish an unknown parameter from a statistic computed on data.',
 'MSE(θ̂) = Var(θ̂) + Bias(θ̂)²', ['probability/random-variables'],
 [('Estimator','A statistic θ̂(X₁,…,Xₙ) used to estimate a parameter θ. Its sampling distribution describes its behavior under repeated samples.'),('Bias and consistency','Bias is Eθ[θ̂]−θ. Consistency means θ̂ₙ→θ in probability as n grows.'),('Likelihood','L(θ;x) is the joint mass or density at the observed data, viewed as a function of θ. Maximum likelihood chooses a maximizing parameter, if one exists.')],
 [('Bias–variance decomposition','With finite second moments, mean squared error E[(θ̂−θ)²] equals variance plus squared bias.'),('Unbiased sample variance','For iid data with finite variance σ² and n≥2, s²=Σᵢ(Xᵢ−X̄)²/(n−1) satisfies E[s²]=σ².')],
 [('Parameter fitting','Likelihood turns model assumptions into an optimization objective.'),('Regularization','Accepting some bias can reduce variance enough to improve prediction error.')],
 ['A likelihood is not a probability distribution over parameters.','Unbiasedness does not guarantee a small error, and a biased estimator can be consistent.'],
 [('Derive','Find the MLE of p from k successes in n independent Bernoulli trials, allowing p∈[0,1].','Maximize k log p+(n−k) log(1−p); handle endpoints separately.','For 0<k<n the derivative vanishes at p=k/n and the log-likelihood is strictly concave. If k=0 or n, the maximum is at 0 or 1. Thus p̂=k/n.'),('Compute','Estimator A has variance 4 and bias 0; B has variance 1 and bias 1. Which has smaller MSE?','Apply the decomposition.','A has MSE 4; B has MSE 1+1²=2. B has smaller MSE despite its bias.')], ['statistics/inference','statistics/regression'])

add('statistics','inference','Confidence intervals & tests','Express sampling uncertainty without confusing the data with the hypothesis.',
 'X̄ ± z₁₋α/₂ σ/√n  (normal data, known σ)', ['probability/limits','statistics/estimation'],
 [('Confidence procedure','A random interval C(X) with coverage Pθ(θ∈C(X))≥1−α for the specified model and parameter range.'),('Null hypothesis and p-value','A p-value is, under the null model, the probability of a test statistic at least as extreme as the observed one in the specified tail or tails.'),('Type I error and power','Type I error rejects a true null. Power is the rejection probability at a specified alternative.')],
 [('Normal mean interval','For iid N(μ,σ²) data with known σ, the displayed interval has exact coverage 1−α. With unknown σ and n≥2, replace σ by s and the normal quantile by a tₙ₋₁ quantile.'),('Union bound for testing','Testing m true null hypotheses each at level α/m gives probability of at least one false rejection at most α, without an independence assumption.')],
 [('Experiments','Intervals show plausible effect sizes and precision; tests quantify incompatibility with a chosen null.'),('Multiple comparisons','Multiplicity corrections help control error when examining many hypotheses.')],
 ['A frequentist 95% confidence statement concerns repeated-sample coverage, not a 95% posterior probability for the fixed parameter.','A p-value is not the probability that the null hypothesis is true. Statistical significance is not effect size.'],
 [('Compute','For normal data with known σ=10, n=100, and X̄=50, give a 95% confidence interval for μ.','Use z₀.₉₇₅≈1.96.','The standard error is 1, so the interval is [48.04,51.96].'),('Compute','What per-test level gives a Bonferroni family-wise level of 0.05 for 20 tests?','Divide the family-wise level by the number of tests.','Use 0.05/20=0.0025 for each test.')], ['statistics/regression','probability/conditioning'])

add('statistics','regression','Linear regression','Fit conditional means while keeping the assumptions behind inference visible.',
 'y = Xβ + ε;     β̂ = (XᵀX)⁻¹Xᵀy  (full column rank)', ['linear-algebra/orthogonality','statistics/estimation'],
 [('Design matrix','An n×p matrix whose rows describe observations and whose columns are predictors, optionally including a column of ones.'),('OLS','Ordinary least squares minimizes ‖y−Xβ‖² over β.'),('Residual','The fitted error e=y−Xβ̂. It is not the unobserved model error ε.')],
 [('OLS unbiasedness','With fixed full-column-rank X and E[ε|X]=0, E[β̂|X]=β.'),('Gauss–Markov','If additionally Var(ε|X)=σ²I, OLS has minimum covariance in the positive-semidefinite order among estimators linear in y and unbiased conditional on X. Normal errors are not required.'),('Residual orthogonality','Every OLS fit satisfies Xᵀe=0. With an intercept, residuals sum to zero.')],
 [('Prediction','Approximate a response from measured features, assessing error on data not used to fit.'),('Adjustment','Include measured covariates to model conditional associations; causal interpretation requires additional design or assumptions.')],
 ['Good fit does not establish causation.','Heteroskedasticity changes standard-error calculations even when OLS remains unbiased.'],
 [('Compute','Fit y=a+bx to points (0,1),(1,3),(2,5).','The points lie exactly on a line.','a=1 and b=2, with all residuals zero.'),('Prove','Why do OLS residuals sum to zero when X contains an intercept?','Use the corresponding entry of Xᵀe.','The intercept column is the all-ones vector. Its inner product with e is Σᵢeᵢ, which is zero by the normal equations.')], ['calculus/multivariable','linear-algebra/eigenvalues'])

add('groups','basics','Groups & subgroups','A group isolates the algebra of reversible operations.',
 '|G| = [G:H] · |H|  (G finite)', ['foundations/proof'],
 [('Group','A set G with an associative binary operation, an identity e, and an inverse for every element.'),('Subgroup','A subset H⊆G that is itself a group under the same operation.'),('Order','The order of a finite group is its size. The order of g is the least positive n with gⁿ=e, if such n exists.')],
 [('Subgroup test','A nonempty subset H of a group is a subgroup if ab⁻¹∈H for every a,b∈H.'),('Lagrange theorem','For a finite group and subgroup H, the left cosets partition G into equal-sized sets, giving |G|=[G:H]|H|. In particular, element orders divide |G|.'),('Prime-order groups','Every group of prime order is cyclic.')],
 [('Symmetry','Rotations and reflections of a geometric object compose into a group.'),('Modular arithmetic','Invertible residue classes form a multiplicative group used in arithmetic algorithms.')],
 ['Lagrange does not imply that every divisor of |G| occurs as a subgroup order.','Groups need not be commutative: permutations are a standard example.'],
 [('Compute','Find the order of 4 in the additive group ℤ/12ℤ.','Find the smallest n>0 with 4n≡0 mod 12.','The order is 3: the generated subgroup is {0,4,8}.'),('Prove','Show a group G of prime order p is cyclic.','Take g≠e and use Lagrange.','The order of g divides p and is not 1, so it is p. Hence its powers exhaust G.')], ['groups/quotients','groups/actions'])

add('groups','quotients','Homomorphisms & quotients','A quotient identifies precisely the information a homomorphism forgets.',
 'G / ker φ ≅ im φ', ['groups/basics','foundations/sets-maps'],
 [('Homomorphism','A map φ:G→H satisfying φ(ab)=φ(a)φ(b). It preserves identity and inverses.'),('Kernel','ker φ={g:φ(g)=e}. It is a normal subgroup of G.'),('Normal subgroup','N◁G means gNg⁻¹=N for all g. Then coset multiplication (gN)(hN)=ghN is well-defined.')],
 [('First isomorphism theorem','For any group homomorphism φ:G→H, the map g ker φ ↦ φ(g) is a well-defined group isomorphism G/ker φ→im φ.'),('Injectivity criterion','A homomorphism is injective exactly when its kernel is {e}.')],
 [('Parity of permutations','The sign homomorphism Sₙ→{±1} has kernel Aₙ; for n≥2 the quotient Sₙ/Aₙ is a group of order 2.'),('Linear algebra bridge','The linear-map analogue identifies V/ker T with im T.')],
 ['A quotient group needs a normal subgroup, not just any subgroup.','The image can be smaller than the codomain; the isomorphism theorem uses the image.'],
 [('Compute','For φ:ℤ→ℤ/5ℤ given by reduction mod 5, find the kernel and quotient.','Which integers map to zero?','ker φ=5ℤ and im φ=ℤ/5ℤ, so ℤ/5ℤ is isomorphic to the quotient by the kernel.'),('Prove','Why is a kernel normal?','Apply φ to gng⁻¹ for n in the kernel.','φ(gng⁻¹)=φ(g)eφ(g)⁻¹=e, so conjugation preserves the kernel. Applying the same reasoning with g⁻¹ gives equality.'),('Connect','For a linear map T: V→W, explain why V/ker T is naturally isomorphic to im T.','Send the coset v+ker T to T(v).','If v−v′∈ker T then T(v)=T(v′), so the map is well-defined. It is linear and onto im T. Its kernel contains only the zero coset, so it is an isomorphism. In finite dimension, taking dimensions recovers rank–nullity.')], ['algebra/rings-fields','representations/basics'])

add('groups','actions','Group actions & counting','Study a group by what it moves and what it fixes.',
 '|Orb(x)| = [G:Stab(x)]', ['groups/basics'],
 [('Action','A map G×X→X with e·x=x and (gh)·x=g·(h·x). Equivalently, a homomorphism G→Sym(X).'),('Orbit','Orb(x)={g·x:g∈G}, the points reachable from x.'),('Stabilizer','Stab(x)={g:g·x=x}, a subgroup of G.')],
 [('Orbit–stabilizer','The map g Stab(x)↦g·x is a bijection. For finite G, |Orb(x)|=|G|/|Stab(x)|.'),('Burnside counting lemma','For a finite group acting on a finite set, the number of orbits equals (1/|G|)Σg |Fix(g)|.')],
 [('Counting up to symmetry','Count colorings, arrangements, or configurations while identifying rotations or other allowed symmetries.'),('Permutation representations','An action on a finite set yields a linear action on the vector space with that set as a basis.')],
 ['An orbit is a subset of X; a stabilizer is a subgroup of G.','Specify the symmetry group: identifying rotations only differs from identifying rotations and reflections.'],
 [('Count','How many binary colorings of three labeled vertices are distinct up to cyclic rotation?','Apply Burnside to the three rotations.','The identity fixes all 8 colorings. Each nonidentity rotation fixes the 2 monochromatic colorings. Thus the count is (8+2+2)/3=4.'),('Compute','S₃ acts on {1,2,3}. Find the stabilizer of 1 and its orbit.','Which permutations leave 1 fixed?','The stabilizer is {e,(23)}, of size 2. The orbit has size 6/2=3 and is {1,2,3}.')], ['representations/basics','representations/characters'])

add('representations','basics','Representations & invariant subspaces','Replace abstract symmetries by matrices that preserve composition.',
 'ρ: G → GL(V),     ρ(gh)=ρ(g)ρ(h)', ['groups/quotients','linear-algebra/spaces-maps'],
 [('Representation','A group homomorphism into the invertible linear maps of a vector space V over a specified field. Its dimension is dim V.'),('Invariant subspace','W⊆V is invariant if ρ(g)W⊆W for every g. A nonzero representation is irreducible if its only invariant subspaces are 0 and V.'),('Intertwiner','A linear map T:V→W with Tρ(g)=σ(g)T for all g. An invertible intertwiner makes the representations equivalent.')],
 [('Maschke theorem','Every finite-dimensional representation of a finite group over a field whose characteristic does not divide |G| is a direct sum of irreducible representations.'),('Schur lemma','An intertwiner between irreducible representations is zero or an isomorphism. For a finite-dimensional irreducible representation over an algebraically closed field, every endomorphism intertwiner is scalar.')],
 [('Symmetry reduction','Decompose linear problems into invariant blocks before computing.'),('Fourier analysis','Characters of finite abelian groups provide elementary Fourier modes.')],
 ['Faithful means the kernel is trivial; irreducible means there are no proper nonzero invariant subspaces. These are different properties.','The characteristic restriction in Maschke is essential.'],
 [('Decompose','C₂ acts on ℝ² by swapping coordinates. Find invariant one-dimensional subspaces.','Use symmetric and antisymmetric vectors.','span{(1,1)} carries the trivial action; span{(1,−1)} carries the sign action. Their direct sum is ℝ².'),('Explain','Is the trivial representation on ℂ² irreducible?','Every group element acts as the identity.','No. Every line is invariant, so there are proper nonzero invariant subspaces.')], ['representations/characters','representations/tensor-products'])

add('representations','characters','Characters & decomposition','Traces summarize finite-group representations without fixing a basis.',
 '⟨χ,ψ⟩ = (1/|G|) Σg∈G χ(g) overline(ψ(g))', ['representations/basics','linear-algebra/eigenvalues'],
 [('Character','χV(g)=tr ρV(g). This sheet assumes finite groups and finite-dimensional complex representations.'),('Class function','A function constant on conjugacy classes. Characters are class functions because trace is unchanged by conjugation.'),('Multiplicity','The number of copies of an irreducible representation in a direct-sum decomposition.')],
 [('Character orthogonality','Irreducible complex characters of a finite group form an orthonormal basis of its class functions under the displayed inner product.'),('Multiplicity formula','If χ is the character of V and χᵢ is irreducible, its multiplicity in V is ⟨χ,χᵢ⟩.'),('Dimension sum','The irreducible complex representation dimensions dᵢ satisfy Σᵢdᵢ²=|G|.')],
 [('Decomposition without eigenvectors','Character inner products recover multiplicities without explicitly finding invariant bases.'),('Permutation actions','The trace of a permutation matrix equals its number of fixed basis elements, linking characters to orbit counting.')],
 ['The character inner product includes complex conjugation.','A character value is not generally an integer, though irreducible multiplicities are nonnegative integers.'],
 [('Compute','For C₂={e,s}, a representation has character (3,1). Decompose it using irreducible characters (1,1) and (1,−1).','Compute the two inner products.','The trivial multiplicity is (3+1)/2=2; the sign multiplicity is (3−1)/2=1.'),('Compute','Find the character of the natural S₃ permutation action on ℂ³ at e, (12), and (123).','Count fixed coordinates.','The character values are 3, 1, and 0 respectively.')], ['groups/actions','representations/tensor-products'])

add('representations','tensor-products','Direct sums, tensor products & duals','Build new representations and track how their dimensions and characters change.',
 'χV⊕W = χV + χW;     χV⊗W = χV χW', ['representations/basics','representations/characters'],
 [('Direct sum','Act independently on V⊕W: g·(v,w)=(g·v,g·w). Dimensions add.'),('Tensor product','The vector space generated by symbols v⊗w subject to bilinearity. The action is g·(v⊗w)=(g·v)⊗(g·w); finite dimensions multiply.'),('Dual representation','On V*=Hom(V,F), define (g·ℓ)(v)=ℓ(g⁻¹·v). The inverse makes this a left action.')],
 [('Character identities','For finite-dimensional representations, direct sums add traces and tensor products multiply them.'),('Dual characters','For a finite group over ℂ, χV*(g)=χV(g⁻¹), which is the complex conjugate of χV(g).'),('Invariant tensors','The invariant subspace of V*⊗W identifies with HomG(V,W), the space of intertwiners.')],
 [('Coupled systems','Tensor products describe combined state spaces on which one symmetry acts simultaneously.'),('Invariant quantities','Trivial summands in tensor products reveal symmetry-invariant combinations.')],
 ['The tensor product of irreducibles need not be irreducible.','The dual action uses the inverse; simply transposing ρ(g) generally reverses the multiplication order.'],
 [('Compute','For the sign representation ε of C₂, identify ε⊗ε.','Square the character values.','Its character is (1,−1)²=(1,1), so it is the trivial representation.'),('Compute','If dim V=2 and dim W=3, what are dim(V⊕W) and dim(V⊗W)?','Dimensions add for sums and multiply for tensors.','They are 5 and 6 respectively. A tensor basis consists of the six pairs of basis vectors.')], ['linear-algebra/spaces-maps','groups/actions'])

